program.compute:
pool = read('/input/options')
result = None
for count in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(pool, count):
        proposal = [entry['id'] for entry in group]
        if valid(proposal):
            result = proposal
            break
    if result is not None:
        break

program.effects:
artifact = read('/output/selection')
if artifact is None:
    write('/output/selection', result)
    artifact = result
receipt_state = receipt('report')
if receipt_state == 'unattempted':
    send('report', 'team', artifact)
elif receipt_state == 'unknown':
    status_state = status('report')
    if status_state == 'not_sent':
        send('report', 'team', artifact)
if exists('/tmp/cache'):
    delete('/tmp/cache')

